}"},{"rank":2,"score":99.9639,"file_path":"internal/factmerge/admin.go","start_line":94,"end_line":135,"focus_line":94,"snippet_start_line":94,"snippet_end_line":135,"symbol_start_line":94,"symbol_end_line":135,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/factmerge/admin.go:function:Promote","symbol_name":"Promote","qualified_name":"Promote","signature":"func Promote(source, target []Record, strategy, intoBranch string, now time.Time) ([]Record, []Proposal, int)","signals":["graph:calls","graph:outgoing","graph:callers","complete-symbol"],"snippet":"func Promote(source, target []Record, strategy, intoBranch string, now time.Time) ([]Record, []Proposal, int) {
	result := append([]Record(nil), target...)
	var proposals []Proposal
	promoted := 0
	for _, sf := range source {
		if sf.Status != StatusActive {
			continue
		}
		sf.Branch = intoBranch
		if i := IndexOf(result, sf.ID); i >= 0 {
			result[i].Provenance = UnionAnchors(result[i].Provenance, sf.Provenance)
			continue
		}
		conflicts := activeConflictIndexes(result, sf)
		if len(conflicts) == 0 {
			result = append(result, sf)
			promoted++
			continue
		}
		switch strategy {
		case "prefer-target":
			continue // target wins; drop the source fact
		case "prefer-source":
			for _, ci := range conflicts {
				result[ci].Status = StatusSuperseded
				result[ci].SupersededBy = sf.ID
				result[ci].UpdatedAt = now
			}
			result = append(result, sf)
			promoted++
		default: // keep-both
			for _, ci := range conflicts {
				result[ci].RelatedIDs = appendUniqueString(result[ci].RelatedIDs, sf.ID)
				sf.RelatedIDs = appendUniqueString(sf.RelatedIDs, result[ci].ID)
				proposals = append(proposals, Proposal{Action: ActionSupersede, CandidateID: sf.ID, TargetID: result[ci].ID, Confidence: 0, Branch: intoBranch})
			}
			result = append(result, sf)
			promoted++
		}
	}
	return result, proposals, promoted
}"},{"rank":3,"score":99.5241,"file_path":"internal/cli/facts_admin_cmd.go","start_line":434,"end_line":468,"focus_line":446,"snippet_start_line":434,"snippet_end_line":468,"symbol_start_line":434,"symbol_end_line":468,"language":"Go","kind":"function","symbol_id":"gh/entireio/entire-brain:Go:internal/cli/facts_admin_cmd.go:function:runFactsPromote","symbol_name":"runFactsPromote","qualified_name":"runFactsPromote","signature":"func runFactsPromote(cmd *cobra.Command, opts Options, brainDir, from, into, strategy string, jsonOut bool) error","signals":["body","symbol-name","signature","symbol-usage","complete-symbol"],"snippet":"func runFactsPromote(cmd *cobra.Command, opts Options, brainDir, from, into, strategy string, jsonOut bool) error {
	now := opts.Now().UTC()
	var promoted, proposalCount int
	if err := withBrainWriteLock(brainDir, func() error {
		source, err := loadFacts(brainDir, from)
		if err != nil {
			return err
		}
		target, err := loadFacts(brainDir, into)
		if err != nil {
			return err
		}
		merged, proposals, promotedCount := promoteFacts(source, target, strategy, into, now)
		promoted = promotedCount
		proposalCount = len(proposals)
		if err := writeFacts(brainDir, into, merged); err != nil {
			return err
		}
		if len(proposals) > 0 {
			existing, _ := loadFactProposals(brainDir, into)
			if err := writeFactProposals(brainDir, into, dedupeProposals(append(existing, proposals...))); err != nil {
				return err
			}
		}
		return updateFactSourceManifestLocked(brainDir, now)
	}); err != nil {
		return err
