    print(' ',r.get('type'),str(r.get('date'))[:16],'|',str(r.get('title'))[:50],'|',r.get('id'))
    print('     snippet:',str(r.get('snippet') or r.get('match') or '')[:400].replace(chr(10),' '))
print('  total',d['total'])"

input.command:
for run in c4-r1 c4-r2 c4-r3 c5-r1 c5-r2 c5-r3; do printf '%s: brain_locked=%s brief_truncated_before_fact=%s brain_version=%s\n' "$run" "$(grep -c brain_locked /tmp/ladder-runs/test-first-checklist/$run/stream.jsonl)" "$(python3 - $run <<'EOF'
import json,sys
run=sys.argv[1]; ids={}; out='n/a'
for line in open(f'/tmp/ladder-runs/test-first-checklist/{run}/stream.jsonl'):
    try: ev=json.loads(line)
    except: continue
    if ev.get('type')=='assistant':
        for b in ev['message'].get('content',[]):
            if b.get('type')=='tool_use': ids[b['id']]=str(b['input'].get('command',''))
    if ev.get('type')=='user':
        for b in ev['message'].get('content',[]):
            if isinstance(b,dict) and b.get('type')=='tool_result' and 'brain brief' in ids.get(b.get('tool_use_id'),''):
                s=b.get('content'); s=s if isinstance(s,str) else json.dumps(s)
                out=f"saw_fact={'exact test first' in s} bytes={len(s)}"
print(out)
EOF
)" "$(cat /tmp/ladder-runs/test-first-checklist/$run/brain_version.txt 2>/dev/null)"; done

